-- Somente no projeto local descartável, depois da migração do ciclo 017. Compara o retrato integral,
-- desconsiderando apenas as sete colunas novas, que precisam estar vazias ou nulas em todas as linhas.
DO $$ begin
if (select linhas from private.retrato_upgrade_172) is distinct from jsonb_build_object('ativos', (select coalesce(jsonb_agg(x.l order by x.l::text),'[]'::jsonb) from (select to_jsonb(a) - array['veiculos_acesso','indexadores_remuneracao','regime_tributario','prazo_resgate_tipo','prazo_resgate_dias','prazo_resgate_unidade','cobertura_fgc'] as l from public.ativos a) x),'eventos', (select coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) from public.eventos x),'transferencias', (select coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) from public.transferencias x),'consolidados_mensais', (select coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) from public.consolidados_mensais x),'posicoes_mensais', (select coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) from public.posicoes_mensais x),'instituicoes', (select coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) from public.instituicoes x),'classes_ativo', (select coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) from public.classes_ativo x),'profiles', (select coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) from public.profiles x)) then raise exception 'retrato financeiro/descritivo divergente'; end if;
if exists (select 1 from public.ativos where veiculos_acesso <> '{}' or indexadores_remuneracao <> '{}' or regime_tributario is not null or prazo_resgate_tipo is not null or prazo_resgate_dias is not null or prazo_resgate_unidade is not null or cobertura_fgc is not null) then raise exception 'atributos preenchidos no upgrade'; end if;
end $$;
select 'retrato integral preservado e atributos vazios' as resultado;
-- Aplicação nova grava atributos; a anterior, depois da migração, edita sem apagá-los.
select set_config('request.jwt.claims','{"sub":"17200000-0000-4000-8000-000000000008","role":"authenticated"}',false);
select set_config('teste.ativo',(select id::text from public.ativos where nome = 'Ativo fictício de upgrade'),false);
select public.editar_ativo_com_atributos(current_setting('teste.ativo')::uuid,'Ativo fictício de upgrade',null,null,'a5000000-0000-4000-8000-000000020000',true,false,null,true,'{fundo}','{cdi}','fundos_longo_prazo','prazo',1,'uteis','nao');
select public.editar_ativo_com_nome(current_setting('teste.ativo')::uuid,'Ativo fictício renomeado',null,null,'a5000000-0000-4000-8000-000000020000',true,false,null,true);
select (veiculos_acesso, indexadores_remuneracao, regime_tributario, prazo_resgate_tipo, prazo_resgate_dias, prazo_resgate_unidade, cobertura_fgc)::text = '({fundo},{cdi},fundos_longo_prazo,prazo,1,uteis,nao)' as app_anterior_preserva_atributos from public.ativos where id = current_setting('teste.ativo')::uuid;
select to_regprocedure('public.cadastrar_ativo_taxonomia(text,public.tipo_ajuste,uuid,text,uuid,boolean,boolean,boolean,boolean)') is not null and to_regprocedure('public.editar_ativo_com_nome(uuid,text,uuid,text,uuid,boolean,boolean,boolean,boolean)') is not null as api_anterior_preservada, to_regprocedure('public.cadastrar_ativo_com_atributos(text,public.tipo_ajuste,uuid,text,uuid,boolean,boolean,boolean,boolean,text[],text[],text,text,integer,text,text)') is not null and to_regprocedure('public.editar_ativo_com_atributos(uuid,text,uuid,text,uuid,boolean,boolean,boolean,boolean,text[],text[],text,text,integer,text,text)') is not null as api_nova_disponivel;
